  on conflict (analysis_id) do update set
    project_id = excluded.project_id, owner_id = excluded.owner_id, data = excluded.data,
    version = excluded.version, saved_at = excluded.saved_at, saved_by = excluded.saved_by,
    mutation_id = excluded.mutation_id, request_signature = excluded.request_signature;

  -- Keep the snapshot policy aligned with the calculation configuration.
  update procurement.current_workbooks
  set data = jsonb_set(data, '{state,policy,versionId}', data #> '{configuration,policyVersionId}')
  where project_id = v_project_id
    and analysis_id in ('f232393a-7ba1-4ad6-8f84-5f4767b1fcd4',
      '796580b4-86b9-4b81-a63d-c3bf27dfd088', '34bc1538-40e3-465c-af04-028ab2db4a9f')
    and data #>> '{state,policy,versionId}' is distinct from data #>> '{configuration,policyVersionId}';
end $$;
commit;

select p.id as project_id, p.name as project_name, a.id as analysis_id, a.name as analysis_name, a.status, c.analysis_date
from procurement.projects p
join procurement.analyses a on a.project_id = p.id and a.owner_id = p.owner_id
join procurement.current_workbooks c on c.analysis_id = a.id and c.owner_id = a.owner_id
where p.id = '11111111-1111-4111-8111-111111111111'
order by a.name;
